website = env.ref('library.website_industry')
MARK = '__EXPORT_FILTER_XMLID__'

def resolve_markers(content):
    new_content = content
    while MARK in new_content:
        start = new_content.index(MARK)
        end = new_content.index(MARK, start + len(MARK)) + len(MARK)
        xmlid = new_content[start + len(MARK):end - len(MARK)]
        try:
            resolved = str(env.ref(xmlid).id)
        except ValueError:
            resolved = '0'
        new_content = new_content[:start] + resolved + new_content[end:]
    return new_content

for view in env['ir.ui.view'].sudo().search([('website_id', '=', website.id)]):
    arch = view.arch_db or ''
    if MARK in arch:
        view.write({'arch_db': resolve_markers(arch)})

for menu in env['website.menu'].sudo().search([('website_id', '=', website.id)]):
    content = menu.mega_menu_content or ''
    if MARK in content:
        menu.write({'mega_menu_content': resolve_markers(content)})
